export const gameplayDomains={common,combat,queue,skills,inventory,rewards,crafting,details};
const rows={...common,...combat,...queue,...skills,...inventory,...rewards,...crafting,...details};
export type GameplayKey=keyof typeof rows;
export const gameplayCatalogs=catalogsFor(rows);
export const gameplayTranslate=createTranslator<GameplayKey>(gameplayCatalogs);

const templates=(Object.keys(rows) as GameplayKey[]).filter(key=>key.includes('{')).map(key=>{
  const names:string[]=[];
  const escaped=key.replace(/[.*+?^$()|[\]\\]/g,'\\$&');
  const pattern=escaped.replace(/\{(\w+)\}/g,(_,name:string)=>{names.push(name);return '(.+?)';});
  return {key,names,pattern:new RegExp('^'+pattern+'$')};
});

// Only call this for authored game presentation, never player-entered text or names.
export function localizeGameplay(language:Language,value:string|undefined):string{
  if(!value)return value??'';
  if(Object.prototype.hasOwnProperty.call(rows,value))return gameplayTranslate(language,value as GameplayKey);
  const key=(Object.keys(rows) as GameplayKey[]).find(entry=>!entry.includes('{')&&entry.toLowerCase()===value.toLowerCase());
  if(key){const translated=gameplayTranslate(language,key);return value===value.toUpperCase()?translated.toLocaleUpperCase(language):translated;}
  for(const template of templates){
    const match=template.pattern.exec(value);
    if(match){const params:Record<string,string>={};template.names.forEach((name,index)=>{params[name]=name==='skill'?localizeGameplay(language,match[index+1]):match[index+1];});return gameplayTranslate(language,template.key,params);}
  }
  return battleText(language,value);
}
export function useGameplayText(){
  const language=useGameLanguage();
  return {language,gt:(key:GameplayKey,params?:Record<string,string|number>)=>gameplayTranslate(language,key,params),gl:(value:string|undefined)=>localizeGameplay(language,value)};
}
